function renderToday(){const log=current(),gym=gymFor(log),done=log.exercises.flatMap(e=>e.sets).filter(s=>s.done).length,total=log.exercises.reduce((n,e)=>n+e.sets.length,0),locked=log.status==='completed',meals=N.dayMacros(state,selectedDate,true);return `<div class="intro meneiHero"><div class="heroCopy"><div class="eyebrow">Your next rep starts here</div><h1>Make progress.<br>Keep the record.</h1><p class="muted">A plan that fits your gym, your shifts, and your goals.</p>${workoutTimingHtml(log)}</div><div class="heroArtwork" aria-hidden="true"><img class="heroCrest" src="./brand-emblem.svg" alt="" width="1536" height="852"><img class="heroAthlete" src="./artwork/greek-athlete-gold.webp" alt="" width="1024" height="1536" fetchpriority="high"></div><div class="heroDate">${dateControl()}</div></div>${state.deviceUpgrade&&!state.deviceUpgrade.acknowledged?`<div class="callout"><b>Your previous workout history has been copied.</b><p>${state.deviceUpgrade.count} workout records restored. Both versions of any conflicting dates remain in History.</p><div class="row wrap">${button('Export original backup','export-original','','small')}${button('Got it','dismiss-upgrade','','small ghost')}</div></div>`:''}${overview(log,done,total,meals)}<div class="columns"><div><div class="card tint"><div class="row between"><div><div class="eyebrow">${h(C.dateOf(selectedDate).toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}))}</div><h2 style="margin:8px 0 4px">${h(log.title)}</h2><div class="sub">${h(gym?.name||'Choose a gym')} · ${log.exercises.length} exercises</div></div><span class="tag ${locked?'':'blue'}">${locked?'COMPLETED':'TODAY’S SESSION'}</span></div><div class="heroMeta"><span class="tag gray">${h(state.training.experience)}</span><span class="tag gray">${h(trainingStyle(log.trainingStyle||state.training.trainingStyle).label)}</span><span class="tag gray">${state.training.frequency} days / week</span>${log.run?`<span class="tag blue">${h(log.run.type||'Easy aerobic run')}</span>`:''}${log.sauna?`<span class="tag gray">${log.sauna.minutes} min sauna</span>`:''}</div><div class="progressBar"><i style="width:${total?Math.min(100,done/total*100):0}%"></i></div><div class="row between"><span class="sub">${done} of ${total} sets checked</span><div class="row wrap">${button('Save routine','save-routine','','small')}${button('Edit session','edit-day','','small')}${button('Supersets','supersets',locked?'disabled':'','small')}</div></div></div>${C.shortSessionTarget(log,state.training)&&!locked?`<div class="callout">This saved generated session has ${log.exercises.length} of ${C.shortSessionTarget(log,state.training)} template exercises. ${button('Restore full session','restore-session','','small')}<p class="tiny">Adds equipment-compatible exercises and keeps all existing sets.</p></div>`:''}${(log.notes||[]).length?`<div class="callout">${log.notes.map(h).join('<br>')}</div>`:''}<div class="sectionTitle" id="todayWorkout"><h2>Your workout</h2>${button('+ Add exercise','picker','', 'small')}</div>${renderWorkout(log,locked)||`<div class="card empty">${log.kind==='rest'?'A recovery day is part of the plan.':'No strength exercises scheduled.'}<p>${button('Build a workout','generator','','primary')}</p></div>`}${log.run||log.sauna?`<div class="card"><h3>Recovery & conditioning</h3>${log.run?`<label class="statRow">Run · ${log.run.minutes} minutes · ${h(log.run.type||'Easy aerobic run')}<input type="checkbox" data-daycheck="run" ${log.run.done?'checked':''} ${locked?'disabled':''}></label>`:''}${log.run?.guidance?`<p class="sub">${h(log.run.intensity)}<br>${h(log.run.guidance)}</p>`:''}${log.sauna?`<label class="statRow">Sauna · ${log.sauna.minutes} minutes<input type="checkbox" data-daycheck="sauna" ${log.sauna.done?'checked':''} ${locked?'disabled':''}></label>`:''}</div>`:''}<div class="sectionTitle">${button(locked?'Unlock completed workout':'Complete workout',locked?'unlock':'complete','',locked?'':'primary')}${button('Skip day','skip','','ghost small')}</div></div><aside class="stack asideStats"><div class="card"><div class="label">Session tools</div><div class="divider"></div><div class="row between"><span class="sub">Rest timer</span><span class="timer" id="restTimer">02:00</span></div><div class="row wrap">${[[60,'1 min'],[90,'90 sec'],[120,'2 min'],[180,'3 min'],[240,'4 min'],[300,'5 min']].map(([s,label])=>button(label,'timer',`data-seconds="${s}"`,'small')).join('')}${button('Stop','stop-timer','','ghost small')}</div>${timerOptionsHtml()}<div class="sub" style="margin-top:12px">Rest starts when you check Done today. Supersets rest after both sets of a round; all working sets finished starts a 3-minute rest screen. Stop is always available. Timers catch up after sleep; sound needs this app open and may be silenced by your phone.</div></div><div class="card"><div class="label">Nutrition today · eaten</div><div class="metric" style="margin-top:12px">${Math.round(meals.protein)} <small>/ ${state.nutrition.protein} g protein</small></div><div class="progressBar"><i style="width:${Math.min(100,meals.protein/(+state.nutrition.protein||1)*100)}%"></i></div><div class="statRow"><span class="muted">Calories</span><b>${Math.round(meals.calories)} / ${state.nutrition.calories}</b></div>${button('Open meal plan','view','data-view="nutrition"','small')}</div><div class="card"><div class="eyebrow">Progress, carried forward</div><h3 style="margin-top:10px">Every set informs the next.</h3><p class="sub">Check off working sets and enter RIR to earn your next load increase. Warm-ups and drop sets stay separate.</p></div>${state.conflicts.length?`<div class="card"><span class="tag amber">${state.conflicts.length} sync conflicts</span><p class="sub">Both versions are preserved for review.</p>${button('Review versions','conflicts','','small')}</div>`:''}</aside></div>`}
function renderWorkout(log,locked){
 const groups=S.supersetGroups(log),shown=new Set();return log.exercises.map((e,index)=>{
  if(shown.has(index))return '';const pair=groups.find(g=>g.members.some(m=>m.index===index));if(!pair)return exerciseCard(e,index,log,locked);
  const status=S.roundStatus(pair);pair.members.forEach(m=>shown.add(m.index));
  return `<section class="supersetBlock" aria-label="Superset ${h(pair.label)}"><div class="supersetHeading"><div><span class="tag blue">SUPERSET ${h(pair.label)}</span><h3>${h(pair.members.map(m=>m.exercise.name).join(' + '))}</h3><p class="sub">One working set of ${pair.label}1 → one of ${pair.label}2 → ${pair.restSeconds} sec rest, then repeat. Warm-up, ramp, back-off and drop sets stay separate. ${status.completed} / ${status.rounds} rounds complete.${status.next?' Next: round '+status.next+'.':''}${status.extraSets.some(Boolean)?' Finish extra sets as straight sets before the final pair rest.':''}</p><p class="tiny">Each exercise earns its own rep and load increases from its checked working sets and RIR. After all working sets of both exercises, take a 3-minute pair rest.</p></div>${button('Start round rest','timer',`data-seconds="${pair.restSeconds}"`,'small')}</div>${pair.members.map(m=>exerciseCard(m.exercise,m.index,log,locked)).join('')}</section>`;
 }).join('');
}
function saveSupersetDay(day){store.snapshot();state.logs[selectedDate]=C.touch(S.cleanSupersets(day));save({render:true})}
function supersetsDialog(){
 const day=current();if(day.status==='completed')throw Error('Unlock this workout before changing supersets.');
 const groups=S.supersetGroups(day),available=day.exercises.map((e,i)=>[i,e.name]).filter(([i])=>!S.entered(day.exercises[i]));
 openModal(`<div class="eyebrow">Session format</div><h2>Progressive overload supersets</h2><p class="sub">Alternate one working set of each exercise, rest between rounds, and repeat. Both exercises keep separate weights, reps, RIR and progression. Superset history is compared with previous superset exposures.</p><div class="row wrap">${button('Auto-pair unstarted exercises','auto-supersets','','small')}${button('Remove unstarted pairs','clear-supersets','','small ghost')}</div><p class="tiny">Auto pairing keeps exercise order, leaves the first exercise and demanding lower-body compounds as straight sets, and pairs neighboring compatible exercises. Choose your own pair below to override it.</p>${groups.map(g=>{const started=g.members.some(m=>S.entered(m.exercise));return `<div class="listItem"><div><b>${h(g.label)} · ${h(g.members.map(m=>m.exercise.name).join(' + '))}</b><div class="sub">${g.restSeconds} sec between rounds · ${started?'Recorded structure protected':'Ready to train'}</div></div>${button('Unpair','unpair',`data-pair="${h(g.id)}" ${started?'disabled':''}`,'small ghost')}</div>`}).join('')}${available.length>=2?`<form id="supersetForm" style="margin-top:18px"><h3>Choose a pair</h3><div class="grid formGrid">${select('Exercise 1','first',available,available[0][0])}${select('Exercise 2','second',available,available[1][0])}${field('Rest between rounds · seconds','restSeconds',state.training.restSeconds||120,'number','min="45" max="300" required')}</div><p class="sub">Choose practical equipment combinations. Warm-up, ramp, back-off and drop sets stay separate. If working-set counts differ, finish the remaining sets normally.</p><button class="btn primary">Save superset</button></form>`:'<p class="sub">Add two unstarted exercises to create another pair. Entered sets and completed workouts keep their recorded structure.</p>'}<p class="tiny">Supersets can save time and feel more demanding. Adjust loads to keep your selected rep range and RIR. <a href="https://pubmed.ncbi.nlm.nih.gov/39903375/" target="_blank" rel="noopener">Superset research</a>.</p>`);
}
function exerciseLoadGuidance(e,log){return {rec:C.progression(state,e,selectedDate,gymFor(log)),next:['completed','skipped'].includes(log.status)?null:C.nextSetRecommendation(state,e,gymFor(log))}}
function nextSetHasLoad(e,next){return !!next&&e.sets[next.targetIndex].w!==''&&e.sets[next.targetIndex].w!=null}
function loadActionLabel(e,next){return next?nextSetHasLoad(e,next)?`Set ${next.targetIndex+1} load entered`:`Use suggestion for set ${next.targetIndex+1}`:'Apply suggested loads'}
function loadGuidanceHtml(e,rec,next){
 const title=next?`Next set ${next.targetIndex+1}: ${next.weight} ${h(state.profile.units)}${next.assistance?' assistance':''} × ${next.reps}`:rec.weight===null?`Target ${h(e.range)} reps`:`Next: ${rec.weight} ${h(state.profile.units)} × ${rec.reps}`;
 const detail=next?`<div class="previous">Based on checked set ${next.sourceIndex+1}: ${next.sourceReps} reps · ${next.sourceRir} RIR</div>`:rec.previous?`<div class="previous">Last ${h(rec.previous.date)}: ${rec.previous.sets.map(s=>`${s.w}×${s.r}${s.rir!==''?' @'+s.rir+' RIR':''}`).join(' · ')}</div>`:'';
 return `<b>${title}</b> · ${h(next?.reason||rec.reason)}${detail}${nextSetHasLoad(e,next)?`<div class="sub">Set ${next.targetIndex+1} has an entered load. Adjust it manually if you want to use this suggestion.</div>`:''}`;
}
function refreshLoadGuidance(index){
 const log=current(),e=log.exercises[index];if(!e)return;
 const {rec,next}=exerciseLoadGuidance(e,log),box=$('loadGuidance-'+index),action=$('applyLoads-'+index);
 if(box)box.innerHTML=loadGuidanceHtml(e,rec,next);
 if(action){action.textContent=loadActionLabel(e,next);action.disabled=log.status==='completed'||nextSetHasLoad(e,next)}
 for(let j=0;j<e.sets.length;j++)for(const key of ['w','r']){const input=document.querySelector(`[data-set="${index}:${j}:${key}"]`);if(input)input.placeholder=j===next?.targetIndex?next[key==='w'?'weight':'reps']:rec.rows[j]?.[key]??(key==='w'?'—':'')}
}
function recommendedEquipment(e,gym,{compact=false}={}){
 const requirements=e.equipmentRequirements||e.equipment,known=Array.isArray(requirements),variant=!!e.needsVariantSelection;
 const label=variant?'Choose an exact variation to see its equipment.':e.equipmentLabel||(known?(requirements.length?requirements.map(c=>(Array.isArray(c)?c:[c]).join(' or ')).join(' + '):'Bodyweight'):'Equipment details need review.');
 const missing=known&&!variant&&gym?C.missingEquipment(e,gym):[];
 const status=known&&!variant&&gym&&requirements.length?`<p class="equipmentStatus ${missing.length?'warningText':'sub'}">${missing.length?'Missing from '+h(gym.name)+' inventory: '+h(missing.join(', ')):'Matches your saved '+h(gym.name)+' inventory'}</p>`:'';
 return `<div class="exerciseEquipment ${compact?'equipmentCompact':''}" role="group" aria-label="Recommended equipment"><div class="label">Recommended equipment</div><p class="equipmentList">${h(label==='Bodyweight'?'Bodyweight · no external equipment':label)}</p>${status}${!compact&&variant?`<ul class="guideList">${(e.variantOptions||[]).map(id=>C.exerciseFor(id)).filter(Boolean).map(v=>`<li><b>${h(v.name)}:</b> ${h(v.equipmentLabel)}</li>`).join('')}</ul>`:''}</div>`;
}
function exerciseCard(e,i,log,locked){const cat=C.exerciseFor(e.exerciseId||e.name)||e,{rec,next}=exerciseLoadGuidance(e,log),pair=S.supersetFor(log,i),pairLabel=pair?pair.label+(pair.members.findIndex(m=>m.index===i)+1):null,label=cat.loadMode==='perHand'?'per hand':cat.loadMode==='assistance'?'assistance':cat.loadMode==='bodyweight'?'added load':state.profile.units;return `<article class="card exercise"><div class="exerciseTop"><span class="exerciseNum">${pairLabel||String(i+1).padStart(2,'0')}</span>${thumbnail(cat)}<div class="grow"><button class="exerciseTitle" data-action="guide" data-exercise="${h(cat.id)}" data-guide-gym="${h(gymFor(log)?.id||'All')}">${h(e.name)}</button><div class="sub">${h(cat.primary||cat.group||'')} · ${e.sets.length} × ${h(e.range)} · ${number((pair?.restSeconds||e.sets.find(s=>['working','top'].includes(s.role))?.rest||120)/60)} min ${pair?'between rounds':'rest'}</div></div><span class="tag gray">${h(e.setType||'straight')}</span></div>${recommendedEquipment(cat,gymFor(log))}<div class="rec" id="loadGuidance-${i}">${loadGuidanceHtml(e,rec,next)}</div><div class="tableWrap"><table class="setTable"><thead><tr><th>Set</th><th>Type</th><th>${h(label)}</th><th>${cat.repUnit==='seconds'?'Seconds':cat.repUnit==='metres'?'Metres':'Reps'}</th><th>RIR</th><th>Done</th></tr></thead><tbody>${e.sets.map((s,j)=>`<tr class="${s.done?'done':''}"><td>${j+1}</td><td><select aria-label="Set ${j+1} role" data-set="${i}:${j}:role" ${locked?'disabled':''}>${['working','warmup','ramp','top','backoff','drop'].map(x=>option(x,x,s.role)).join('')}</select></td>${[['w','number',(j===next?.targetIndex?next.weight:rec.rows[j]?.w)??'—'],['r','number',(j===next?.targetIndex?next.reps:rec.rows[j]?.r)??''],['rir','number','2']].map(([key,type,placeholder])=>`<td><input aria-label="${h(e.name)} set ${j+1} ${key==='w'?'weight':key==='r'?(['seconds','metres'].includes(cat.repUnit)?cat.repUnit:'reps'):'RIR'}" data-set="${i}:${j}:${key}" type="${type}" inputmode="${key==='r'&&!['seconds','metres'].includes(cat.repUnit)?'numeric':'decimal'}" min="0" ${key==='rir'?'max="10"':''} step="${key==='w'?'0.5':key==='r'&&['seconds','metres'].includes(cat.repUnit)?'any':'1'}" value="${h(s[key])}" placeholder="${placeholder}" ${locked?'disabled':''}></td>`).join('')}<td><input aria-label="Complete set ${j+1}" type="checkbox" data-set="${i}:${j}:done" ${s.done?'checked':''} ${locked?'disabled':''}></td></tr>`).join('')}</tbody></table></div><div class="exerciseActions">${button('Edit sets','sets',`data-index="${i}" ${locked?'disabled':''}`,'small')}${pair?'':button('Start set rest','timer',`data-seconds="${e.sets.find(s=>['working','top'].includes(s.role))?.rest||120}"`,'small')}${button(loadActionLabel(e,next),'apply-loads',`id="applyLoads-${i}" data-index="${i}" ${locked||nextSetHasLoad(e,next)?'disabled':''}`,'small')}${button('Swap','picker',`data-index="${i}" ${locked?'disabled':''}`,'small ghost')}${button('Remove','remove-exercise',`data-index="${i}" ${locked?'disabled':''}`,'small ghost')}</div></article>`}
function renderProgram(){const start=C.addDays(selectedDate,programOffset),dates=Array.from({length:28},(_,i)=>C.addDays(start,i)),range=start+' – '+dates[27];const month=C.dateOf(selectedDate),first=new Date(month.getFullYear(),month.getMonth(),1),count=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();return `<div class="intro row between wrap"><div><div class="eyebrow">Built around your life</div><h1>Your training calendar.</h1><p class="muted">An ongoing calendar with fresh workouts, runs, recovery and gym schedules.</p></div><div class="row wrap">${button('Custom block','custom-block','','small')}${button('Original 28-day plan','original-program','','small')}${button('Generate a program','generator','','primary')}</div></div>${state.sessionSizeRepair?`<div class="callout">Restored full session lengths in ${state.sessionSizeRepair.count} unstarted generated workouts. Recorded sessions and custom routines were kept.</div>`:''}<div class="columns"><div class="card"><div class="row between"><h2>${h(first.toLocaleDateString(undefined,{month:'long',year:'numeric'}))}</h2>${dateControl()}</div><div class="calendar">${['S','M','T','W','T','F','S'].map(x=>`<div class="calHead">${x}</div>`).join('')}${'<div></div>'.repeat(first.getDay())}${Array.from({length:count},(_,i)=>{const date=C.iso(new Date(first.getFullYear(),first.getMonth(),i+1)),log=C.dayFor(state,date),gym=state.gyms.find(g=>g.id===log.gymId),scheduled=C.scheduledGym(state,date),label=date+' · '+log.title+' · Workout gym: '+(gym?.name||'Unassigned')+' · Scheduled gym: '+(scheduled?.name||'Unassigned')+(scheduled?.id==='station'?' · Scheduled Fire Station marker':'');return `<button class="calDate ${date===selectedDate?'active':''} ${log.status==='completed'?'completed':''}" data-action="open-date" data-date="${date}" aria-label="${h(label)}" title="${h(label)}">${i+1} ${scheduled?.id==='station'?'<i class="shiftDot" title="Scheduled Fire Station marker" aria-hidden="true"></i>':''}<small>${h(log.title)}</small><small>Workout gym: ${h(gym?.name||'Unassigned')}</small></button>`}).join('')}</div><div class="sub" style="margin-top:14px">Gold dot: scheduled Fire Station marker · Gold underline: completed session. Workout gyms reflect saved or planned sessions; schedules can differ.</div><div class="sectionTitle"><h2>28-day schedule · ${h(range)}</h2><div class="row">${button('←','program-page','data-offset="-28"','small')}${button('→','program-page','data-offset="28"','small')}</div></div>${dates.map(date=>{const log=C.dayFor(state,date),gym=state.gyms.find(g=>g.id===log.gymId);return `<div class="planDay"><div class="dateBlock">${C.dateOf(date).toLocaleDateString(undefined,{weekday:'short'})}<b>${C.dateOf(date).getDate()}</b></div><div><h3 style="font-size:14px">${h(log.title)}</h3><div class="sub">${h(gym?.name||'Unassigned')} · ${log.exercises.length} exercises ${log.run?'· Run':''}${log.sauna?' · Sauna':''}</div>${log.status==='completed'?'<span class="tag">Completed</span>':''}</div>${button('Open','open-date',`data-date="${date}"`,'small')}</div>`}).join('')}</div><aside class="stack"><div class="card"><div class="eyebrow">Program builder</div><h3 style="margin-top:12px">Your preferences</h3><div class="statRow"><span>Frequency</span><b>${state.training.frequency} / week</b></div><div class="statRow"><span>Structure</span><b>${h(SPLITS.find(s=>s[0]===state.training.split)?.[1]||state.training.split)}</b></div><div class="statRow"><span>Focus</span><b>${h(trainingStyle(state.training.trainingStyle).label)}</b></div><div class="statRow"><span>Format</span><b>${state.training.supersetMode==='supersets'?'Supersets + progression':'Straight sets'}</b></div><div class="statRow"><span>Avoid repeats</span><b>${state.training.minRepeatDays} days</b></div><div class="statRow"><span>Runs</span><b>${state.training.runEvery?'Every '+state.training.runEvery+' days':'Off'}</b></div><p class="sub">The calendar keeps generating beyond the preview. Logged sessions are protected during generation. Limited equipment may require repeats; the plan explains each one.</p>${button('Change preferences','generator','','small')}</div><div class="card"><h3>Firefighter schedule</h3>${state.gymSchedules.filter(r=>!r.deleted).map(r=>`<p class="sub">${h(state.gyms.find(g=>g.id===r.gymId)?.name)} · ${r.type==='weekly'?'Weekly':`Every ${r.every} ${r.type==='weeks'?'weeks':'days'}`} · from ${h(r.start)}</p>`).join('')}${button('Edit gym schedules','view','data-view="settings"','small')}</div><div class="card"><h3>Calendar reminders</h3><p class="sub">Export ${h(range)} to your phone’s calendar. Times use your calendar’s local time. Unfinished sessions include a 15-minute alert.</p>${button('Export '+h(range)+' (.ics)','calendar-export','data-scope="program"','small')}</div></aside></div>`}
function renderLibrary(){const gyms=state.gyms.filter(g=>!g.deleted),selectedGym=libraryFilter.gym==='All'?null:gyms.find(g=>g.id===libraryFilter.gym);const list=[...C.CATALOG,...state.customExercises].filter(e=>!e.deleted&&(libraryFilter.group==='All'||e.group===libraryFilter.group)&&(libraryFilter.equipment==='All'||e.equipmentRequirements.some(clause=>clause.includes(libraryFilter.equipment)))&&(libraryFilter.gym==='All'||C.supports(e,selectedGym))&&(!libraryFilter.q||[e.name,e.primary,e.equipmentLabel,...e.aliases].join(' ').toLowerCase().includes(libraryFilter.q.toLowerCase())));return `<div class="intro row between wrap"><div><div class="eyebrow">Learn the movement</div><h1>Your exercise library.</h1><p class="muted">${C.CATALOG.length} audited exercises. Exact equipment, clear cues, saved history.</p></div>${button('+ Custom exercise','custom-exercise','','primary')}</div><div class="filterRow"><input id="librarySearch" aria-label="Search exercises" placeholder="Search an exercise or muscle…" value="${h(libraryFilter.q)}"><select id="libraryGroup" aria-label="Filter by muscle">${['All','Chest','Back','Legs','Shoulders','Biceps','Triceps','Core','Full Body'].map(g=>option(g,g==='All'?'All muscles':g,libraryFilter.group)).join('')}</select><select id="libraryEquipment" aria-label="Filter by equipment">${option('All','All equipment',libraryFilter.equipment)}${C.EQUIPMENT.map(e=>option(e,e,libraryFilter.equipment)).join('')}</select><select id="libraryGym" aria-label="Filter by gym equipment">${option('All','Every gym',libraryFilter.gym)}${gyms.map(g=>option(g.id,g.name,libraryFilter.gym)).join('')}</select></div><div class="libraryGrid">${list.slice(0,libraryLimit).map(e=>{const m=mediaFor(e);return `<button class="card libItem" data-action="guide" data-exercise="${h(e.id)}" data-guide-gym="${h(libraryFilter.gym)}">${thumbnail(e)}<h3>${h(e.name)}</h3><p class="sub">${h(e.group)} · ${h(e.loadMode==='perHand'?'Per dumbbell':e.loadMode)}</p>${recommendedEquipment(e,selectedGym,{compact:true})}<span class="tag ${m?.startPath&&m?.finishPath?'gray':'amber'}">${m?.startPath&&m?.finishPath?'Reference pair recovered':'Media incomplete'}</span></button>`}).join('')}</div>${!list.length?'<div class="empty">No exercises match. Try another filter.</div>':''}${list.length>libraryLimit?`<div class="sectionTitle">${button(`Show more (${list.length-libraryLimit} remaining)`,'more-library','','primary')}</div>`:''}<p class="sub" style="margin-top:24px">Recovered image revisions are retained. Approval history is not encoded in the source files; the app marks uncertain media for verification.</p>`}
function renderNutrition(){const dates=state.meals[selectedDate],planned=N.dayMacros(state,selectedDate),eaten=N.dayMacros(state,selectedDate,true),n=N.targetsForDate(state,selectedDate);return `<div class="intro row between wrap"><div><div class="eyebrow">Fuel the work</div><h1>Train. Eat. Recover.</h1><p class="muted">${h(n.dayType)} · ${h(n.nextDayType)} · meals matched to your plan.</p></div><div class="row wrap">${button('Recipes · '+N.ORIGINAL_RECIPES.length,'nutrition-tab','data-tab="recipes"','small')}${button('Nutrition options','nutrition-setup','','small')}${dateControl()}</div></div>${!state.nutrition.setupCompleted?`<div class="callout row between wrap"><span>Start with your current goal, diet and food choices.</span>${button('Set up nutrition','nutrition-setup','','primary small')}</div>`:''}<div class="macroGrid">${[['calories','Calories','kcal'],['protein','Protein','g'],['carbs','Carbs','g'],['fat','Fat','g']].map(([key,label,unit])=>`<div class="macro"><div class="label">${label}</div><p><strong>${Math.round(eaten[key])}</strong> <small>/ ${n[key]} ${unit}</small></p><div class="progressBar"><i style="width:${Math.min(100,eaten[key]/(+n[key]||1)*100)}%"></i></div><small>${Math.round(planned[key])} ${unit} planned</small></div>`).join('')}</div><div class="pillNav">${[['meals','Today’s Meals'],['schedule','Meal Schedule'],['recipes','Recipes'],['pantry','Pantry'],['shopping','Shopping list'],['targets','Targets & preferences']].map(([id,title])=>`<button data-action="nutrition-tab" data-tab="${id}" class="${nutritionTab===id?'active':''}">${title}</button>`).join('')}</div>${nutritionTab==='meals'?`<div class="columns"><div class="card"><div class="row between"><h2>Your meals</h2><div class="row">${button('Shopping','nutrition-tab','data-tab="shopping"','small')}${button('Import recipes','recipe-upload','','small')+button('+ Meal','add-meal','','small')}</div></div>${(dates?.items||[]).filter(m=>!m.deleted).map((m,i)=>{const r=m.recipeSnapshot||state.recipes.find(r=>r.id===m.recipeId),macros=r?N.recipeMacros(r,+m.servings||1):null;return `<div class="mealRow"><div class="mealIcon">${m.eaten?'✓':'◷'}</div><div><div class="eyebrow">${h(m.slot)} ${h(m.time||'')}</div><h3>${h(r?.name||'Recipe unavailable')}</h3><div class="sub">${macros?`${Math.round(macros.calories)} kcal · ${Math.round(macros.protein)}g protein · ${m.servings} personal servings`:''}</div><div class="tiny">Cooking ${m.householdServings||m.servings} servings for the household</div></div><div class="row wrap">${button('Cook','cook',`data-id="${h(m.id)}"`,'small')}${button(m.eaten?'Eaten ✓':'Mark eaten','eaten',`data-id="${h(m.id)}"`,'small '+(m.eaten?'ghost':'primary'))}${button('Edit','edit-meal',`data-id="${h(m.id)}"`,'small ghost')}${button('×','remove-meal',`data-id="${h(m.id)}" aria-label="Remove meal"`,'small ghost')}</div></div>`}).join('')||'<div class="empty">Your day is ready for a meal plan.</div>'}</div><aside class="stack"><div class="card tint"><div class="eyebrow">A week of good fuel</div><h3 style="margin-top:12px">Build your meal plan.</h3><p class="sub">Choose recipes that fit your diet and exclusions, then balance portions against your targets. Existing and eaten meals are protected.</p>${button('Generate 7 days','meal-generator','','primary')}</div><div class="card"><h3>Use what you have.</h3><p class="sub">Pantry stock is allocated by meal date and expiry. Shopping quantities cover the household; macro totals track your personal portions.</p>${button('Review pantry','nutrition-tab','data-tab="pantry"','small')}</div><div class="card"><h3>Recipe estimates</h3><p class="sub">Built-in macros are approximate. Match your food labels and raw or cooked weighing method when editing recipes.</p></div></aside></div>`:nutritionTab==='schedule'?renderMealSchedule():nutritionTab==='recipes'?renderRecipes():nutritionTab==='pantry'?renderPantry()+leftoversHtml():nutritionTab==='shopping'?renderShopping():renderTargets()}`}
function renderRecipes(){const active=state.recipes.filter(r=>!r.deleted),matched=active.filter(r=>{const m=N.recipeMacros(r),minutes=(r.prepMinutes??Infinity)+(r.cookMinutes??Infinity);return (!recipeFilter.q||[r.name,...r.ingredients.map(i=>i.name)].join(' ').toLowerCase().includes(recipeFilter.q.toLowerCase()))&&(recipeFilter.slot==='All'||(r.slots||[]).includes(recipeFilter.slot))&&(recipeFilter.fit!=='compatible'||N.allowedRecipe(r,state.nutrition))&&(recipeFilter.fit!=='protein'||m.protein>=25)&&(recipeFilter.fit!=='higher-carb'||m.carbs>=50)&&(recipeFilter.fit!=='lower-carb'||m.carbs<30)&&(recipeFilter.time==='any'||minutes<=+recipeFilter.time)&&(!recipeFilter.batch||r.servings>=3)});return `<div class="row between wrap"><div><h2>Your recipes</h2><p class="sub">${active.length} saved recipes · ${matched.length} match your filters</p></div><div class="row wrap">${button('Upload recipes','recipe-upload','','small')}${button('Export recipes','recipes-export','','small')}${button('+ Create recipe','recipe','','primary')}</div></div><div class="filterRow recipeFilters"><input id="recipeSearch" aria-label="Search recipes or ingredients" placeholder="Search a meal, flavor or ingredient…" value="${h(recipeFilter.q)}"><select id="recipeSlot" aria-label="Filter recipes by meal">${['All','Breakfast','Lunch','Dinner','Snack'].map(v=>option(v,v==='All'?'All meals':v,recipeFilter.slot)).join('')}</select><select id="recipeFit" aria-label="Filter recipes by nutrition">${[['all','All recipes'],['compatible','Fits my diet & exclusions'],['protein','25g+ protein / serving'],['higher-carb','50g+ carbs / serving'],['lower-carb','Under 30g carbs / serving']].map(([v,l])=>option(v,l,recipeFilter.fit)).join('')}</select><select id="recipeTime" aria-label="Filter recipes by total time">${[['any','Any prep/cook time'],['20','20 minutes or less'],['30','30 minutes or less'],['45','45 minutes or less']].map(([v,l])=>option(v,l,recipeFilter.time)).join('')}</select><label class="sub"><input id="recipeBatch" type="checkbox" ${recipeFilter.batch?'checked':''}> Batch recipes · 3+ servings</label></div><p class="sub">AI-authored originals include full instructions and approximate macros; they are not kitchen tested. Meal generation scales portions to your training/recovery targets. Existing meals stay saved.</p><div class="grid">${matched.slice(0,recipeLimit).map(r=>{const m=N.recipeMacros(r),allowed=N.allowedRecipe(r,state.nutrition);return `<div class="card"><div class="row between wrap"><div class="label">${h((r.slots||[]).join(' · ')||'Any meal')}</div><span class="tag ${allowed?'gray':'amber'}">${allowed?'Fits your options':'Excluded from planner'}</span></div><h3 style="margin-top:10px">${h(r.name)}</h3><div class="sub">${Math.round(m.calories)} kcal · P ${Math.round(m.protein)} · C ${Math.round(m.carbs)} · F ${Math.round(m.fat)} / serving</div><p class="tiny">${r.ingredients.length} ingredients · ${r.servings||1} recipe yield${r.prepMinutes!==undefined?` · ${r.prepMinutes} min prep · ${r.cookMinutes||0} min cook`:''}</p><p class="tiny">${h(r.aiGenerated||r.collection?'AI-authored original · not kitchen tested':r.source||'Your saved recipe')}</p>${r.allergenReviewRequired?'<p class="warningText">Custom ingredients: review allergens before automatic planning with exclusions.</p>':''}<div class="row wrap">${button('View recipe','recipe-view',`data-id="${h(r.id)}"`,'small')}${button('Plan this meal','plan-recipe',`data-id="${h(r.id)}"`,'small')}${button('Edit','recipe',`data-id="${h(r.id)}"`,'small ghost')}${button('Archive','archive-recipe',`data-id="${h(r.id)}"`,'small ghost')}</div></div>`}).join('')||'<div class="card empty">No matching recipes. Try another filter or upload a collection.</div>'}</div>${matched.length>recipeLimit?`<div class="sectionTitle">${button('Show more recipes','more-recipes','','small')}<span class="sub">${recipeLimit} of ${matched.length} shown</span></div>`:''}`}
function renderMealSchedule(){return `<div class="row between wrap"><h2>Your next 7 days of meals</h2>${button('Generate meal schedule','meal-generator','','primary')}</div><div class="grid">${Array.from({length:7},(_,i)=>{const date=C.addDays(selectedDate,i),targets=N.targetsForDate(state,date),macros=N.dayMacros(state,date),meals=state.meals[date]?.items.filter(m=>!m.deleted)||[];return `<div class="card"><div class="row between"><b>${h(C.dateOf(date).toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'}))}</b><span class="tag ${targets.dayType==='Training day'?'blue':'gray'}">${targets.dayType}</span></div><p class="sub">${Math.round(macros.calories)} / ${targets.calories} kcal · P ${Math.round(macros.protein)} / ${targets.protein}g</p>${meals.map(m=>`<p class="sub">${h(m.time||m.slot)} · ${h(m.recipeSnapshot?.name||state.recipes.find(r=>r.id===m.recipeId)?.name)}</p>`).join('')||'<p class="sub">No meals planned.</p>'}${button('Open meals','meal-date',`data-date="${date}"`,'small')}</div>`}).join('')}</div>`}
function leftoversHtml(){return `<div class="sectionTitle"><h2>Prepared leftovers</h2>${button('Use leftovers','use-leftover','','small')}</div><div class="card">${(state.leftovers||[]).filter(l=>!l.deleted).map(l=>`<div class="listItem"><div><b>${h(l.name)}</b><div class="sub">${number(N.leftoversAvailable(state,l))} servings available · use by ${h(l.expiry)}${l.expiry<selectedDate?' · expired':''}</div></div>${button('Remove','remove-leftover',`data-id="${h(l.id)}"`,'small ghost')}</div>`).join('')||'<p class="sub">Save cooked servings from a meal’s recipe, then schedule them within their use-by date.</p>'}</div><p class="sub">Next 3 days: ${N.shoppingList(state,selectedDate,3).items.length} ingredients to buy · Next 5 days: ${N.shoppingList(state,selectedDate,5).items.length} ingredients to buy. Review expiry dates before relying on leftovers.</p>`}
function renderPantry(){return `<div class="row between"><div><h2>Your pantry</h2><p class="sub">Track quantities and expiry. Stock is never counted twice across meals.</p></div>${button('+ Add ingredient','pantry','','primary')}</div><div class="card tableWrap"><table class="dataTable"><thead><tr><th>Ingredient</th><th>Available</th><th>Use by</th><th></th></tr></thead><tbody>${state.pantry.filter(p=>!p.deleted).map(p=>`<tr><td>${h(p.name)}</td><td>${foodQuantity(p.qty,p.unit)}</td><td class="${p.expiry&&p.expiry<selectedDate?'warningText':''}">${h(p.expiry||'—')}</td><td>${button('Edit','pantry',`data-id="${h(p.id)}"`,'small')}${button('Remove','remove-pantry',`data-id="${h(p.id)}"`,'small ghost')}</td></tr>`).join('')}</tbody></table>${state.pantry.filter(p=>!p.deleted).length?'':'<div class="empty">Add the ingredients you already have.</div>'}</div>`}
function renderShopping(){const list=N.shoppingList(state,selectedDate,+state.nutrition.horizon||7);return `<div class="row between wrap"><div><h2>Buy what’s missing.</h2><p class="sub">From ${selectedDate} · household portions · expired stock excluded</p></div><div class="row"><select id="shoppingHorizon" aria-label="Shopping period">${[1,3,7].map(x=>option(x,`${x} day${x===1?'':'s'}`,state.nutrition.horizon)).join('')}</select>${button('Add checked purchases','buy-checked','','small')}${button('Export list','shopping-export','','small')}</div></div><div class="card">${list.items.map(x=>`<label class="listItem"><div><input type="checkbox" data-shop="${h(x.id)}" ${state.shoppingChecks[x.id]?.checked?'checked':''}> <b>${h(x.name)}</b><div class="sub">${foodQuantity(x.qty,x.unit)} needed · ${foodQuantity(x.have,x.unit)} on hand</div><div class="tiny">${h(x.aisle)}${x.packages?` · ${x.packages} × ${foodQuantity(x.packageQty,x.unit)} suggested packages`:''}</div></div></label>`).join('')||'<div class="empty">No missing ingredients. Plan meals to build a shopping list.</div>'}${list.warnings.length?`<div class="callout">${list.warnings.map(h).join('<br>')}</div>`:''}</div><p class="sub">Suggested packages use editable reference sizes; store packaging varies. Different units are converted only when compatible.</p>`}
function preferenceChecks(label,name,options,selected=[]){return `<fieldset class="preferenceGroup"><legend>${label}</legend><div class="preferenceChoices">${options.map(([value,title])=>`<label><input type="checkbox" name="${name}" value="${h(value)}" ${selected.includes(value)?'checked':''}><span>${h(title)}</span></label>`).join('')}</div></fieldset>`}
function renderTargets(inModal=false){const n=state.nutrition;return `<form id="targetsForm" class="${inModal?'':'card'}"><h2>Nutrition options</h2><h3 class="formSection">1 · Your current target</h3><div class="grid formGrid">${select('Current goal','goal',[['muscle','Build muscle'],['fat-loss','Lose body fat'],['recomposition','Build muscle & lose fat'],['maintain','Maintain & perform'],['custom','Custom target']],n.goal||'muscle')}${select('Diet style','diet',['Any','High protein','Mediterranean','Lower carb','Vegetarian','Vegan'],n.diet||'Any')}${field('Household servings multiplier','servings',n.servings,'number','min="0.25" max="20" step="0.25" required')}${field('Minimum days before meal repeat','mealRepeatDays',n.mealRepeatDays??2,'number','min="0" max="14"')}</div><p class="sub">Your goal describes the plan. Enter the calorie target you want to use below; changing a goal will keep your targets until you edit them.</p><h3 class="formSection">2 · Foods you want to eat</h3>${preferenceChecks('Main meals','mealCategories',N.PREFERENCE_OPTIONS.meal,n.mealCategories)}${preferenceChecks('Breakfast','breakfastCategories',N.PREFERENCE_OPTIONS.breakfast,n.breakfastCategories)}${preferenceChecks('Snacks','snackCategories',N.PREFERENCE_OPTIONS.snack,n.snackCategories)}<p class="sub">Select as many as you like. Preferences guide recipe choice; exclusions below always take priority.</p>${preferenceChecks('Allergens to exclude','allergens',[['milk','Milk / dairy'],['egg','Eggs'],['fish','Fish'],['shellfish','Shellfish'],['peanut','Peanuts'],['tree nut','Tree nuts'],['soy','Soy'],['wheat','Wheat'],['sesame','Sesame']],n.allergens)}${field('Other foods / allergens to avoid · comma separated','exclude',n.exclude,'text','placeholder="e.g. mushrooms, mustard"')}<details class="collapsible"><summary>Specific favorite foods</summary>${field('Main meal favorites','preferredFoods',n.preferredFoods||'')}${field('Breakfast favorites','breakfastFoods',n.breakfastFoods||'')}${field('Snack favorites','snackFoods',n.snackFoods||'')}</details><h3 class="formSection">3 · Daily macro targets</h3><div class="grid formGrid">${field('Calories','calories',n.calories,'number','min="1" required')}${field('Protein · g','protein',n.protein,'number','min="0" required')}${field('Carbs · g','carbs',n.carbs,'number','min="0" required')}${field('Fat · g','fat',n.fat,'number','min="0" required')}</div>${button('Suggest macros for this diet style','diet-macros','','small')}<details class="collapsible"><summary>Training, recovery & tomorrow</summary><p class="sub">These targets follow the workout calendar automatically. On recovery days before training, you can choose a separate carbohydrate target.</p><div class="grid formGrid">${field('Training-day calories · optional','trainingCalories',n.trainingCalories??'','number','min="1"')}${field('Recovery-day calories · optional','restCalories',n.restCalories??'','number','min="1"')}${field('Training-day carbs · g','trainingCarbs',n.trainingCarbs??'','number','min="0"')}${field('Recovery-day carbs · g','restCarbs',n.restCarbs??'','number','min="0"')}${field('Recovery before training · carbs · optional','preTrainingCarbs',n.preTrainingCarbs??'','number','min="0"')}</div></details><label class="field">Notes<textarea name="notes">${h(n.notes)}</textarea></label><p class="sub">Your current macros calculate ${Math.round(+n.protein*4+ +n.carbs*4+ +n.fat*9)} kcal using 4/4/9. Recipe macros are estimates. Check your product labels and cross-contact information for allergens. Saving options preserves existing meals; generate future empty days to use your changes.</p><div class="modalButtons"><button class="btn primary">${inModal?'Save nutrition & finish setup':'Save nutrition options'}</button></div><div class="error"></div></form>`}
function renderHistory(){const logs=Object.values(state.logs).filter(l=>!l.deleted&&l.exercises?.some(e=>e.sets?.some(s=>s.done||s.w!==''||s.r!==''))).sort((a,b)=>b.date.localeCompare(a.date)),volume=logs.reduce((sum,l)=>sum+l.exercises.reduce((a,e)=>a+e.sets.filter(s=>s.done&&s.role!=='warmup').reduce((a,s)=>a+(+s.w||0)*(+s.r||0)*(e.loadMode==='perHand'?2:1),0),0),0);return `<div class="intro row between wrap"><div><div class="eyebrow">Your work, kept safe</div><h1>Every session counts.</h1><p class="muted">Real logs, original backups, and your progression history.</p></div><div class="row">${button('Import backup','import','','small')}${button('Export backup','export','','primary')}</div></div><div class="grid3"><div class="card"><div class="label">Saved sessions</div><div class="metric">${logs.length}</div></div><div class="card"><div class="label">Completed workouts</div><div class="metric">${logs.filter(l=>l.status==='completed').length}</div></div><div class="card"><div class="label">Logged external volume</div><div class="metric">${Math.round(volume).toLocaleString()} <small>${h(state.profile.units)}</small></div><p class="tiny">Per-hand dumbbell loads count twice. Machine stacks and bodyweight are not comparable across equipment.</p></div></div><div id="historyStrengthPanel" class="historyProgress">${strengthPanel('history')}</div><div class="sectionTitle"><h2>Your sessions</h2>${button('Exercise progress','progress','','small')}</div><div class="card">${logs.map(l=>`<div class="listItem"><div><b>${h(l.title)}</b><div class="sub">${h(l.date)} · ${h(gymFor(l)?.name)} · ${l.exercises.flatMap(e=>e.sets).filter(s=>s.done).length} checked sets</div>${l.legacyKey?'<span class="tag gray">Imported history</span>':''}</div>${button('Review','review-log',`data-id="${h(l.id)}"`,'small')}</div>`).join('')||'<div class="empty">Import your current app’s JSON backup, or log your first workout.</div>'}</div>${state.conflicts.length?`<div class="callout">${state.conflicts.length} versions need review. ${button('Review conflicts','conflicts','','small')}</div>`:C.reviewedConflicts(state).length?`<div class="callout">${C.reviewedConflicts(state).length} reviewed copies remain available for recovery. ${button('Reviewed copies','conflicts','','small')}</div>`:''}<details class="collapsible"><summary>Backup & migration details</summary><p class="sub">Version 8 keeps your original device records intact. Importing merges your logs and retains the full original snapshot, including fields version 8 does not use. Duplicate-date records are retained separately. ${state.legacySnapshots.filter(snapshot=>snapshot?.kind!=='reviewed-conflict').length} original snapshots saved.</p><p class="sub">Original device history is copied on first launch. For records entered in the private beta or on another device, import its exported backup or sign in to the same cloud account.</p></details>`}
function renderSettings(){const p=state.profile,r=state.reminders,previewRevision=document.documentElement?.dataset?.previewRevision,previewBuild=(localPreview||testCloudPreview)&&/^[a-f0-9]{12}$/.test(previewRevision||'')?' · Preview build '+previewRevision:'';return `<div class="intro"><div class="eyebrow">Make it yours</div><h1>Your training workspace.</h1><p class="muted">Profile, equipment, shift schedules, cloud, and notifications.</p></div><div class="callout row between wrap"><span>Running ${h(C.VERSION)}${h(previewBuild)} · ${N.ORIGINAL_RECIPES.length} original recipes · ${state.recipes.filter(r=>!r.deleted).length} saved recipes</span><a class="btn small" href="./update.html">Refresh latest version</a></div><div class="grid"><div class="stack"><form id="profileForm" class="card"><div class="row">${avatarHtml(p)}<div><h2>Your profile</h2><span class="sub">Your photo and profile travel with your backup and cloud account.</span></div></div><div class="row wrap photoActions">${button('Upload profile photo','upload-photo','','small')}${safePhoto(p.photo)?button('Remove photo','remove-photo','','small ghost'):''}</div><p class="tiny">Choose a photo from your phone or computer. It is center-cropped and resized before saving.</p><div class="divider"></div>${field('Name','name',p.name)}<div class="grid formGrid">${select('Gender','gender',['Male','Female'],p.gender)}${field('Age','age',p.age,'number','min="13" max="120"')}${field('Body weight','weight',p.weight,'number','min="0" step="0.1"')}${field('Goal weight','goalWeight',p.goalWeight,'number','min="0" step="0.1"')}${p.units==='kg'?field('Height · cm','heightCm',p.heightFt!==''||p.heightIn!==''?number((+p.heightFt||0)*30.48+(+p.heightIn||0)*2.54):'','number','min="0" max="300" step="0.1"'):field('Height · feet','heightFt',p.heightFt,'number','min="0" max="8"')+field('Height · inches','heightIn',p.heightIn,'number','min="0" max="11.99" step="0.01"')}${select('Measurement system','measurementSystem',[['us','US customary · lb / oz / fl oz'],['metric','Metric · kg / g / ml']],N.measurementSystem(p))}<p class="tiny">Changing systems converts saved workout/body weights on Save. Food amounts follow this system; nutrition macros stay in grams. Values shown now use ${h(p.units)}.</p></div><div class="label" style="margin-bottom:10px">Muscle map skin tone</div><div class="skinSwatches">${Object.entries({light:'#e7c4b0',medium:'#ba8c70',tan:'#ad7959',brown:'#76523d',dark:'#4c352b'}).map(([name,color])=>`<label><i style="background:${color}"></i><input type="radio" name="skinTone" value="${name}" ${p.skinTone===name?'checked':''}>${name}</label>`).join('')}</div><p class="sub">Recovered exercise photos retain their approved appearance. The muscle map reflects your selection.</p><button class="btn primary">Save profile</button><div class="error"></div></form><div class="card"><div class="row between"><h2>Your gyms</h2>${button('+ Gym','gym','','small')}</div>${state.gyms.filter(g=>!g.deleted).map(g=>`<div class="listItem"><div><b>${h(g.name)}</b><div class="sub">${g.inventory.length} equipment types · dumbbells to ${g.dbMax||'—'} lb</div><div class="tiny">${h(g.notes)}</div><div class="tiny">${g.equipmentConfirmedAt?'Checklist confirmed by you '+h(g.equipmentConfirmedAt.slice(0,10))+' · ':''}${g.sourceInfo?.url?'Published source checked '+h(g.sourceInfo.checked)+' · remaining equipment user-entered / estimated':g.sourceInfo?.estimates?.length?'Includes editable estimates for this gym type. Review the equipment checklist.':'Equipment is user-entered or estimated; review this inventory.'}</div></div>${button('Edit','gym',`data-id="${h(g.id)}"`,'small')}</div>`).join('')}</div><div class="card"><div class="row between"><h2>Gym schedules</h2>${button('+ Schedule','schedule','','small')}</div><p class="sub">A 24-on / 72-off shift is every 4 days for 1 day. Higher-priority rules win when schedules overlap.</p>${state.gymSchedules.filter(r=>!r.deleted).map(r=>`<div class="listItem"><div><b>${h(state.gyms.find(g=>g.id===r.gymId)?.name)}</b><div class="sub">${r.type==='weekly'?`Weekdays ${(r.weekdays||[]).map(d=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][+d]).join(', ')}`:`Every ${r.every} ${r.type==='weeks'?'weeks':'days'} · ${r.durationDays||1} day(s)`} · from ${h(r.start)}</div><div class="tiny">Priority ${r.priority||0}</div></div>${button('Edit','schedule',`data-id="${h(r.id)}"`,'small')}</div>`).join('')}</div></div><div class="stack"><div class="card"><div class="eyebrow">Lifting & running</div><h2 style="margin-top:10px">Your ongoing program</h2><p class="sub">${h(SPLITS.find(s=>s[0]===state.training.split)?.[1]||'Original program')} · ${h(trainingStyle(state.training.trainingStyle).label)}</p><p class="sub">Choose Full Body, Upper/Lower, PPL or Bro split, sets, reps, rest and goal-matched running.</p>${button('Edit lifting & running options','generator','','small')}</div><div class="card tint"><div class="eyebrow">Food & fuel</div><h2 style="margin-top:10px">Nutrition options</h2><p class="sub">${h(({muscle:'Build muscle','fat-loss':'Lose body fat',recomposition:'Build muscle & lose fat',maintain:'Maintain & perform',custom:'Custom target'})[state.nutrition.goal]||'Choose your current goal')} · ${h(state.nutrition.diet)} · ${state.nutrition.calories} kcal</p><p class="sub">Select diet style, main meals, breakfast, snacks and allergies, then set training and recovery targets.</p>${button(state.nutrition.setupCompleted?'Edit nutrition options':'Set up nutrition','nutrition-setup','','primary')}</div><div class="card"><h2>Help & getting started</h2><p class="sub">A tour of workouts, meals, gym schedules and backups.</p>${button('Health & safety','safety-info','','small')}${button('Quick tour','tutorial','','small')}</div>${localPreview?'<div class="card"><h2>Private preview</h2><p class="sub">Test data is saved on this device. Cloud accounts, sync and scheduled push are disabled here. Your live app stays separate.</p><a class="btn small" href="./preview-guide.html">Testing checklist</a></div>':`<form id="cloudForm" class="card"><div class="row between"><h2>${needsBetaAdmission()?'MENEI account':testCloudPreview?'Private beta cloud account':'Cloud account'}</h2><span class="tag blue">${needsBetaAdmission()?'MENEI':'SUPABASE'}</span></div><p class="sub">${needsBetaAdmission()?'Your MENEI account keeps this beta workspace in sync across your devices. Use synthetic test entries.':testCloudPreview?'This is a separate private beta test account. Your live account and history stay separate. Use synthetic test entries.':'Your cloud connection is configured. Sign in or create your account. Changes queue on this device when offline; original backups remain available.'}</p>${testCloudPreview?'':`<details class="collapsible"><summary>Advanced connection settings</summary>${field('Project URL','url',cloud.config?.url||'','url','placeholder="https://your-project.supabase.co" required')}${field('Publishable / anon key','key',cloud.config?.key||'','password','autocomplete="off" required')}<button class="btn small">Save connection</button></details>`}<div class="divider"></div>${!testCloudPreview&&runtimeConfig.authSettingsUrl?`<div class="callout">Before first signup or password reset, add this app’s address to <a href="${h(runtimeConfig.authSettingsUrl)}" target="_blank" rel="noopener">Supabase Auth → Redirect URLs</a>:<p><code style="overflow-wrap:anywhere">${h(new URL('./',location.href).href)}</code></p>Keep your existing GitHub redirect. This one-time setting cannot be changed through the connected integration.</div>`:''}${field('Email','email',cloud.session?.user?.email||'','email','autocomplete="email"')}${field('Password','password','','password','autocomplete="current-password"')}<div class="row wrap">${needsBetaAdmission()?'':button('Sign in','signin','','primary')+button('Create account','signup','','small')}${button('Sign out','signout','','small')}${button('Reset password','reset-password','','small ghost')}${button('Set new password','change-password','','small ghost')}</div>${needsBetaAdmission()?'<p class="tiny">To switch accounts, sign out; your saved workspaces stay separate.</p>':''}<p id="connectionStatus" class="sub">${h(cloud.lastStatus)}</p>${testCloudPreview&&cloud.disabled?button('Retry test connection','retry-test-cloud','','small'):''}<div class="row wrap">${button('Sync now','sync','','small')}${testCloudPreview?'':button('Import original cloud backup','legacy-cloud','','small')}${button('Review conflicts','conflicts','','small')}</div><div class="error"></div></form>${testCloudPreview?`<div class="card"><h2>Notifications</h2><p class="sub">Scheduled push stays disabled in this test preview.</p>${button('Export calendar alerts','calendar-export','','small')}</div>`:`<form id="reminderForm" class="card"><h2>Notifications</h2><div class="grid formGrid">${field('Reminder time','time',r.time,'time','required')}${field('Time zone','timezone',r.timezone,'text','required')}</div><div class="checks"><label><input name="workout" type="checkbox" ${r.workout?'checked':''}> Workout reminders</label><label><input name="meals" type="checkbox" ${r.meals?'checked':''}> Meal reminder</label></div><p class="sub">${runtimeConfig.pushServiceReady?'The scheduled reminder service is active. Sign in, save your reminder time, then enable push on this device. Test delivery with the app closed.':'Closed-app push needs the included reminder service to be configured.'}</p><details class="collapsible"><summary>Advanced push settings</summary>${field('VAPID public key','vapid',localStorage.getItem('MGT_BETA_VAPID')||'','text','autocomplete="off"')}</details><div class="row wrap"><button class="btn small">Save reminders</button>${button('Enable push','enable-push','','primary')}${button('Test device notification','test-notification','','small')}${button('Disable push','disable-push','','small ghost')}${button('Export calendar alerts','calendar-export','','small')}</div><div class="error"></div></form>`}`}<div class="card"><h2>Your data</h2><p class="sub">Keep a backup before importing or changing devices. Version 8 keeps your original device records intact.</p><div class="row wrap">${button('Export backup','export','','primary')}${button('Import / merge backup','import','','small')}${button('Saved device snapshots','snapshots','','small')}${U.originalDeviceBackup(localStorage)?button('Copy previous device history','copy-original','','small'):''}</div><p class="tiny">${C.VERSION} · ${state.ownerId?'Account workspace':'Guest workspace'} · all features unlocked</p></div><details class="collapsible"><summary>Help & version checks</summary><p class="sub">1. Import your existing JSON backup.<br>2. Review your gym inventory and schedules.<br>3. Generate a program and inspect its warnings.<br>4. Check sets as you train; RIR drives progression.<br>5. Generate meals, adjust recipes, and review shopping.<br>6. Sign in to your cloud account.<br>7. Test sign-in/sync with two devices and RLS with two accounts before sharing.</p><p class="sub">${testCloudPreview?'Private beta help':'Supabase setup'}: <a href="./setup.html">${testCloudPreview?'Test checklist':'Cloud & push instructions'}</a>. The current version preserves original device records for recovery.</p></details></div></div>`}
function generatorDialog(){const t=state.training,preset=trainingStyle(t.trainingStyle);openModal(`<form id="generatorForm"><div class="eyebrow">Automatic workout builder</div><h2>Build your ongoing program.</h2><p class="sub">Preview up to a year. The calendar continues automatically beyond the saved preview with new exercise selections, gym rules and progression; it does not replay the same 28 workouts.</p><div class="grid formGrid">${field('Start date','start',selectedDate,'date','required')}${select('Preview length','days',[[28,'4 weeks'],[42,'6 weeks'],[84,'12 weeks'],[168,'24 weeks'],[364,'52 weeks']],84)}${select('Lifting split','split',SPLITS,t.split)}${select('Workout format','supersetMode',[['off','Straight sets'],['supersets','Supersets · progressive overload']],t.supersetMode||'off')}${select('Training focus','trainingStyle',Object.entries(TRAINING_STYLES).map(([k,v])=>[k,v.label]),t.trainingStyle||'hypertrophy')}${select('Training days / week','frequency',[1,2,3,4,5,6,7],t.frequency)}${select('Experience','experience',['Beginner','Intermediate','Advanced'],t.experience)}${select('Default gym','defaultGym',state.gyms.filter(g=>!g.deleted).map(g=>[g.id,g.name]),t.defaultGym)}${field('Working sets / exercise','sets',t.sets,'number','min="2" max="6" required')}${field('Rep range','range',t.range,'text','pattern="[0-9]{1,2}(-[0-9]{1,2})?" required')}${field('Rest between working sets · seconds','restSeconds',t.restSeconds||preset.rest,'number','min="45" max="300" step="15" required')}${field('Minimum days before repeating','minRepeatDays',t.minRepeatDays,'number','min="0" max="42" required')}${select('Running frequency','runEvery',[[0,'No runs'],[2,'About every 2 days'],[3,'About every 3 days'],[4,'About every 4 days']],t.runEvery)}${field('Sauna after strength · minutes','saunaMinutes',t.saunaMinutes,'number','min="0" max="60"')}</div><p class="sub">Every generated lifting session needs 6–9 total exercises. Superset pairs count as two exercises. Split defaults contain 6–9 exercises per lifting session; your original paired split uses 9 / 8 / 8 / 8. Equipment limits appear in the preview. Supersets keep the exercise count and track progression separately for each exercise.</p><div class="callout" id="trainingStyleSummary"><b>${h(preset.summary)}</b><p>${h(preset.cue)}</p></div><label class="sub"><input name="runningQuality" type="checkbox" ${t.runningQuality?'checked':''}> Include controlled running intervals for endurance focus when recovery allows</label><p class="sub">Runs are mostly conversational aerobic work. Lower-body days and adjacent days use shorter recovery runs; demanding intervals need a clear recovery window. Beginners use easy run/walk sessions. These are adjustable starting plans, not a promise of one best program.</p><fieldset><legend>No lifting on these weekdays</legend><div class="checks">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((x,i)=>`<label><input name="restWeekdays" type="checkbox" value="${i}" ${t.restWeekdays.includes(i)?'checked':''}> ${x}</label>`).join('')}</div></fieldset><label class="sub"><input name="excludePullups" type="checkbox" ${t.excludePullups?'checked':''}> Exclude pull-ups & chin-ups from automatic workouts</label><p class="sub">Entered workouts are protected. The preview explains equipment limits and unavoidable repeats. <a href="https://acsm.org/resistance-training-guidelines-update-2026/" target="_blank" rel="noopener">Training guidance</a> · <a href="https://pubmed.ncbi.nlm.nih.gov/34757594/" target="_blank" rel="noopener">Combining lifting and aerobic work</a>.</p><div class="modalButtons"><button class="btn primary">Preview ongoing program</button></div></form>`)}
function showGuide(id,{gymId}={}){const e=C.exerciseFor(id)||state.customExercises.find(x=>x.id===id);if(!e)throw Error('Exercise not found.');const g=C.guideFor(e),m=mediaFor(e),gym=gymId===undefined?gymFor(current()):gymId==='All'?null:state.gyms.find(value=>value.id===gymId&&!value.deleted),context=gymId??gym?.id??'All';openModal(`<div class="eyebrow">${h(e.group)} · ${h(e.loadMode)}</div><h2>${h(e.name)}</h2>${recommendedEquipment(e,gym)}${context==='All'?'<p class="sub">Every gym · Equipment requirements shown without checking a saved gym inventory.</p>':''}<div class="guideMedia">${[['startPath','Start'],['finishPath','Finish']].map(([key,label])=>`<figure>${m?.[key]?`<img src="./${h(m[key])}" alt="${h(e.name)} ${label.toLowerCase()} reference">`:`<div class="mediaMissing">Matching ${label.toLowerCase()} image not recovered</div>`}<figcaption>${label}${m?.[key]?' · recovered reference':''}</figcaption></figure>`).join('')}</div>${m?.startPath||m?.finishPath?'<p class="warningText">Approval history needs verification. Original revisions are retained.</p>':''}${e.needsVariantSelection?`<div class="callout">This legacy label combines variants. Choose an exact movement when adding or swapping.</div>`:''}<div class="grid"><div class="card compact">${muscleMap(e.group)}<div class="sub"><b>Primary:</b> ${h(e.primary)}<br><b>Secondary:</b> ${h(e.secondary)}</div></div><div><h3>Setup</h3><ol class="guideList">${g.setup.map(x=>`<li>${h(x)}</li>`).join('')}</ol></div></div><div class="grid" style="margin-top:20px"><div><h3>Form cues</h3><ul class="guideList">${g.cues.map(x=>`<li>${h(x)}</li>`).join('')}</ul></div><div><h3>Common mistakes</h3><ul class="guideList">${g.mistakes.map(x=>`<li>${h(x)}</li>`).join('')}</ul></div></div><p class="sub">${h(e.loadNote||'Enter the displayed external load consistently.')}</p><div class="row wrap">${button('Add to this session','add-from-guide',`data-exercise="${h(e.id)}"`,'primary')}${button(state.avoided.includes(e.id)?'Allow in generator':'Avoid in generator','avoid',`data-exercise="${h(e.id)}" data-guide-gym="${h(context)}"`,'small')}${button('View progression','progress',`data-exercise="${h(e.id)}"`,'small')}${m?.gallery?.length?button('Image revisions','media-gallery',`data-media="${h(m.id)}"`,'small'):''}</div>`)}
function pickerDialog(index){if(current().status==='completed')throw Error('Unlock the completed workout before editing.');const gym=gymFor(current());openModal(`<h2>${index===undefined?'Add an exercise':'Choose a replacement'}</h2><p class="sub">Equipment available at ${h(gym?.name)}. Choose an exact movement and setup.</p><input id="pickerSearch" placeholder="Search exercises…" aria-label="Search exercises"><div id="pickerList" data-index="${index??''}"></div>`);renderPicker('')}
function renderPicker(q){const holder=$('pickerList');if(!holder)return;const index=holder.dataset.index,gym=gymFor(current());holder.innerHTML=[...C.CATALOG,...state.customExercises].filter(e=>!e.deleted&&!e.needsVariantSelection&&C.supports(e,gym)&&e.name.toLowerCase().includes(q.toLowerCase())).map(e=>`<div class="listItem"><div><b>${h(e.name)}</b><div class="tiny">${h(e.equipmentLabel)}</div></div>${button('Choose','choose-exercise',`data-exercise="${h(e.id)}" data-index="${index}"`,'small')}</div>`).join('')||'<div class="empty">No match for this gym’s equipment. Update the inventory in Settings.</div>'}
function setsDialog(i){const e=current().exercises[i];if(current().status==='completed')throw Error('Unlock this workout first.');openModal(`<form id="setsForm" data-index="${i}"><h2>Set structure · ${h(e.name)}</h2><div class="grid formGrid">${select('Structure','setType',[['straight','Straight working sets'],['ramp','Ramp to one working set'],['top','Top set + back-off'],['drop','Working set + drops']],e.setType||'straight')}${field('Total sets','count',e.sets.length,'number','min="1" max="12" required')}${field('Rep range','range',e.range,'text','required')}${field('Back-off reduction · %','backoffPercent',e.backoffPercent||10,'number','min="1" max="50"')}${field('Drop reduction each step · %','dropPercent',e.dropPercent||20,'number','min="1" max="60"')}${field('Load increment · '+state.profile.units,'increment',e.increment||'','number','min="0.1" step="0.1"')}</div><p class="sub">Top sets and final ramp sets drive progression. Back-off and drop loads are calculated separately. You can change any row to a warm-up or working set.</p><div class="modalButtons"><button class="btn primary">Save structure</button></div></form>`)}
function gymDialog(id){cancelGymSearch();pendingGymSource=null;pendingGymPreview=null;gymSelectedResearch=null;gymResearchLocations=[];gymResearchContext=null;gymSearchSequence++;const g=state.gyms.find(g=>g.id===id)||{id:'',name:'',inventory:[],dbMax:0,increment:5,notes:''};const all=[...new Set([...C.EQUIPMENT,...C.CATALOG.flatMap(e=>e.equipmentRequirements.flat()),...(g.inventory||[])])].sort();const rendered={...g,name:g.name||'',location:g.location||'',address:g.address||'',inventory:all.filter(name=>C.normalizedInventory(g).has(name))};gymEditContext={id:g.id,confirmedAt:g.equipmentConfirmedAt||null,confirmedFingerprint:gymConfirmationFingerprint(rendered)};openModal(`<form id="gymForm" data-id="${h(g.id)}"><h2>${id?'Edit gym':'Build your gym'}</h2>${field('Gym name','name',g.name,'text','required')}${field('City / state or location','location',g.location||'','text','placeholder="e.g. Pleasant Hills, PA"')}${field('Street address · optional','address',g.address||'','text','placeholder="Confirm the exact location"')}<div class="row wrap">${button(needsBetaAdmission()?'Search gym with AI':'Search location with AI','gym-ai-search',gymResearchAvailable()?'':'disabled','small')}${button('Look up published equipment','gym-lookup','','small')}</div>${gymResearchAvailable()?'':'<p class="tiny">Live AI search is not connected in this preview. Published location lookup and common setup suggestions are available.</p>'}<div class="divider"></div>${select('Gym type for common equipment suggestions','gymType',Object.entries(GYM_TYPES).map(([key,type])=>[key,type.label]),g.gymType||'custom')}<p class="sub">Start with published location facts when available and an estimated common setup. Common suggestions use unbranded equipment types; research can add sourced brands and machine variants. Check each estimate before saving.</p>${button('Preview equipment autofill','gym-autofill','','small')}<div id="gymLookupResults" class="lookupResults" aria-live="polite"></div>${g.sourceInfo?.url?`<p class="sub">Published source checked ${h(g.sourceInfo.checked)} · <a href="${h(safeWebUrl(g.sourceInfo.url))}" target="_blank" rel="noopener">Saved source</a></p>`:''}<div class="row wrap" style="margin:10px 0">${button('Select all','equipment-preset','data-preset="all"','small')}${button('Clear','equipment-preset','data-preset="clear"','small')}${button('Station basics','equipment-preset','data-preset="station"','small')}${button('Confirm my equipment','confirm-equipment','','small')}</div><div class="equipGrid">${all.map(x=>`<label><input name="equipment" type="checkbox" value="${h(x)}" ${C.normalizedInventory(g).has(x)?'checked':''}> ${h(x)} <span data-equipment-evidence="${h(x)}"></span></label>`).join('')}</div><div class="grid formGrid" style="margin-top:15px">${field('Dumbbell max · '+state.profile.units+' each','dbMax',gymLimitForDisplay(g.dbMax),'number','min="0" step="any"')}${field('Increment · lb','increment',g.increment||5,'text','inputmode="decimal" list="loadStepsLb" required')+field('Increment · kg','incrementKg',g.incrementKg||2.5,'text','inputmode="decimal" list="loadStepsKg" required')+'<datalist id="loadStepsLb"><option value="2.5"><option value="5"><option value="10"></datalist><datalist id="loadStepsKg"><option value="1"><option value="1.25"><option value="2.5"><option value="5"></datalist>'}${button('Use 5 lb / 2.5 kg steps','gym-default-steps','','small')}</div><label class="field">Notes<textarea name="notes">${h(g.notes)}</textarea></label><p class="sub">Tick attachments, rack, plates and bench as well as the main machine. A generic cable does not imply every attachment. Saved equipment is used for workout compatibility; remove incorrect suggestions before saving.</p><div class="modalButtons">${id?button('Archive gym','archive-gym',`data-id="${h(id)}"`,'danger'):''}<button class="btn primary">Save gym</button></div></form>`);refreshGymEvidence()}
function scheduleDialog(id){const r=state.gymSchedules.find(r=>r.id===id)||{id:'',gymId:'station',type:'interval',every:4,start:'2026-10-04',durationDays:1,priority:10,weekdays:[]};openModal(`<form id="scheduleForm" data-id="${h(r.id)}"><h2>Gym recurrence</h2><div class="grid formGrid">${select('Gym','gymId',state.gyms.filter(g=>!g.deleted).map(g=>[g.id,g.name]),r.gymId)}${select('Repeat rule','type',[['interval','Every X days'],['weeks','Every X weeks'],['weekly','Weekly on weekdays']],r.type)}${field('Every X days / weeks','every',r.every||4,'number','min="1" max="365" required')}${field('Start date','start',r.start,'date','required')}${field('Consecutive days per recurrence','durationDays',r.durationDays||1,'number','min="1" max="365" required')}${field('Priority','priority',r.priority||0,'number','min="0" max="100"')}${field('End date · optional','end',r.end||'','date')}</div><fieldset><legend>For weekly rules</legend><div class="checks">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((x,i)=>`<label><input name="weekdays" type="checkbox" value="${i}" ${(r.weekdays||[]).map(Number).includes(i)?'checked':''}> ${x}</label>`).join('')}</div></fieldset><p class="sub">A 24-on / 72-off pattern uses every 4 days, 1 consecutive day. Schedules apply when a new program is generated; existing logs are retained.</p><div class="modalButtons">${id?button('Remove rule','remove-schedule',`data-id="${h(id)}"`,'danger'):''}<button class="btn primary">Save schedule</button></div></form>`)}
function recipeDialog(id){const r=state.recipes.find(r=>r.id===id)||{id:'',name:'',servings:1,slots:['Lunch'],ingredients:[],steps:[],tags:[],calories:500,protein:40,carbs:50,fat:15};const macro=N.recipeMacros(r);openModal(`<form id="recipeForm" data-id="${h(r.id)}"><h2>${id?'Edit recipe':'Create a recipe'}</h2>${field('Recipe name','name',r.name,'text','required')}<div class="grid formGrid">${field('Recipe yield · servings','servings',r.servings||1,'number','min="0.25" step="0.25" required')}${select('Meal slot','slot',['Breakfast','Lunch','Dinner','Snack'],r.slots?.[0]||'Lunch')}${select('Diet suitability','diet',['Any','Vegetarian','Vegan'],r.tags?.includes('Vegan')?'Vegan':r.tags?.includes('Vegetarian')?'Vegetarian':'Any')}</div><div class="grid formGrid">${field('Prep minutes · optional','prepMinutes',r.prepMinutes??'','number','min="0" max="1440"')}${field('Cook minutes · optional','cookMinutes',r.cookMinutes??'','number','min="0" max="1440"')}</div><label class="field">Ingredients · one per line: quantity | unit | ingredient<textarea name="ingredients" style="min-height:150px" required>${h(r.ingredients.map(i=>`${i.qty} | ${i.unit} | ${i.name}`).join('\n'))}</textarea></label><p class="sub">Stored quantities below preserve the recipe's exact units. Cooking views and shopping use your selected system. Use g, kg, oz, lb, ml, l, fl oz or each. Built-in food names link to the food values; custom ingredients use your entered per-serving totals.</p><label class="field">Cooking steps · one per line<textarea name="steps" style="min-height:120px">${h(Array.isArray(r.steps)?r.steps.join('\n'):r.steps)}</textarea></label><div class="grid formGrid">${field('Calories / serving','calories',Math.round(macro.calories),'number','min="0" required')}${field('Protein g / serving','protein',number(macro.protein),'number','min="0" step="0.1" required')}${field('Carbs g / serving','carbs',number(macro.carbs),'number','min="0" step="0.1" required')}${field('Fat g / serving','fat',number(macro.fat),'number','min="0" step="0.1" required')}</div><label class="sub"><input name="manualMacros" type="checkbox" ${r.manualMacros?'checked':''}> Use my entered macros instead of ingredient estimates</label><div class="divider"></div>${field('Source / author · optional','source',r.source||'')}${field('Original source URL · optional','sourceUrl',r.sourceUrl||'','url')}<label class="field">Storage & reheating<textarea name="storage">${h(r.storage||'')}</textarea></label><label class="sub"><input name="aiGenerated" type="checkbox" ${r.aiGenerated||r.collection?'checked':''}> AI-authored recipe · not kitchen tested</label>${preferenceChecks('Known allergens','recipeAllergens',[['milk','Milk'],['egg','Egg'],['fish','Fish'],['shellfish','Shellfish'],['peanut','Peanut'],['tree nut','Tree nuts'],['soy','Soy'],['wheat','Wheat'],['sesame','Sesame']],r.allergens)}<label class="sub"><input name="reviewedAllergens" type="checkbox" ${!r.allergenReviewRequired?'checked':''}> I checked the ingredients and product allergen labels.</label><div class="modalButtons"><button class="btn primary">Save recipe</button></div></form>`)}
function showRecipe(r,meal){if(!r)throw Error('Recipe not found.');const f=meal?(meal.householdServings||meal.servings||1)/(+r.servings||1):1,steps=Array.isArray(r.steps)?r.steps:String(r.steps||'').split('\n').filter(Boolean);openModal(`<div class="eyebrow">${h(meal?.slot||'Recipe')}</div><h2>${h(r.name)}</h2><p class="sub">${h(r.aiGenerated||r.collection?'AI-authored original · not kitchen tested':r.source||'Your saved recipe')}${r.sourceUrl?` · <a href="${h(safeWebUrl(r.sourceUrl))}" target="_blank" rel="noopener">Supplied source</a>`:''}${r.prepMinutes!==undefined?` · ${r.prepMinutes} min prep · ${r.cookMinutes} min cook`:''}</p><p class="sub">Ingredients for ${number((+r.servings||1)*f)} cooking servings${meal?` · your portion ${meal.servings} servings`:''}</p><div class="card compact">${r.ingredients.map(i=>`<label class="statRow ingredientCheck"><span><input type="checkbox" ${meal?`data-cook-ingredient="${h(meal.id)}:${r.ingredients.indexOf(i)}"`:''} ${meal?.doneIngredients?.includes(r.ingredients.indexOf(i))?'checked':''}> ${h(i.name)}</span><b>${foodQuantity(+i.qty*f,i.unit)}</b></label>`).join('')}</div>${meal?`<div class="row wrap" style="margin-top:14px">${button('Save leftover servings','leftover',`data-id="${h(meal.id)}"`,'small')}${button('Use saved leftovers','use-leftover','','small')}</div>`:''}<h3 style="margin-top:22px">Cooking steps</h3><div class="recipeSteps">${steps.map((step,i)=>`<label><input type="checkbox" ${meal?`data-cook-step="${h(meal.id)}:${i}"`:''} ${meal?.doneSteps?.includes(i)?'checked':''}> <span>${h(step)}</span></label>`).join('')}</div>${meal&&!meal.leftoverId?button(meal.pantryConsumed?'Pantry already adjusted':'Deduct cooking ingredients from pantry','consume-pantry',`data-id="${h(meal.id)}" ${meal.pantryConsumed?'disabled':''}`,'small'):''}${r.storage?`<p class="sub">${h(r.storage)}</p>`:''}<p class="tiny"><a href="https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures" target="_blank" rel="noopener">FoodSafety.gov cooking temperatures</a> · <a href="https://www.foodsafety.gov/food-safety-charts/cold-food-storage-charts" target="_blank" rel="noopener">Storage guidance</a>. Macros are estimates based on your saved recipe.</p>`)}
function mealDialog(id,recipeId){const picked=state.recipes.find(r=>r.id===recipeId);const m=state.meals[selectedDate]?.items.find(m=>m.id===id)||{id:'',recipeId:recipeId||state.recipes.find(r=>!r.deleted)?.id,slot:picked?.slots?.[0]||'Lunch',servings:1,householdServings:state.nutrition.servings};openModal(`<form id="mealForm" data-id="${h(m.id)}"><h2>${id?'Edit meal':'Add a meal'}</h2>${select('Recipe','recipeId',[...(m.recipeSnapshot?[[m.recipeId,m.recipeSnapshot.name+' · saved meal recipe']]:[]),...state.recipes.filter(r=>!r.deleted&&(!m.recipeSnapshot||r.id!==m.recipeId)).map(r=>[r.id,r.name])],m.recipeId)}${m.recipeSnapshot?'<p class="sub">Keeping this recipe preserves its saved ingredients and instructions. Choosing another recipe uses its current library version.</p>':''}<div class="grid formGrid">${select('Meal','slot',['Breakfast','Lunch','Dinner','Snack'],m.slot)}${field('Meal time · optional','time',m.time||'','time')}${field('Your personal servings','servings',m.servings,'number','min="0.25" max="20" step="0.25" required')}${field('Total cooking servings · household','householdServings',m.householdServings||m.servings,'number','min="0.25" max="100" step="0.25" required')}</div><div class="modalButtons"><button class="btn primary">Save meal</button></div></form>`)}
function pantryDialog(id){const p=state.pantry.find(p=>p.id===id)||{id:'',name:'',qty:100,unit:'g',expiry:''};openModal(`<form id="pantryForm" data-id="${h(p.id)}"><h2>${id?'Edit pantry ingredient':'Add to your pantry'}</h2>${field('Ingredient name','name',p.name,'text','list="foods" required')}<datalist id="foods">${N.FOODS.map(f=>`<option value="${h(f.name)}"></option>`).join('')}</datalist><div class="grid formGrid">${field('Quantity','qty',p.qty,'number','min="0" step="0.1" required')}${select('Unit','unit',['g','kg','oz','lb','ml','l','each'],p.unit)}${field('Use-by date · optional','expiry',p.expiry,'date')}</div><p class="sub">Match ingredient names to your recipes for accurate subtraction. Raw/dry and cooked foods need separate entries.</p><div class="modalButtons"><button class="btn primary">Save ingredient</button></div></form>`)}
let pendingProgram=null,pendingMeals=null,pendingBackup=null,backupReadSequence=0,installPrompt=null,waitingWorker=null;
$('modal').addEventListener('cancel',()=>{pendingMeals=null;pendingBackup=null;backupReadSequence++});
function showAppUpdate(worker){waitingWorker=worker;$('appUpdate').hidden=false}
async function registerOffline(){
 const reg=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});
 const watch=worker=>{if(!worker)return;const changed=()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)showAppUpdate(reg.waiting||worker)};worker.addEventListener('statechange',changed);changed()};
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(registerOffline.applying)location.reload()});
 if(reg.waiting)showAppUpdate(reg.waiting);watch(reg.installing);reg.addEventListener('updatefound',()=>watch(reg.installing));
 const check=()=>reg.update().catch(()=>{});await check();window.addEventListener('online',check);document.addEventListener('visibilitychange',()=>{if(!document.hidden)check()});return reg;
}
function download(name,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportBackup(){download(`muscle-growth-tracker-v8-${C.iso()}.json`,JSON.stringify(state,null,2));notify('Backup exported.')}
function editable(){if(current().status==='completed')throw Error('Unlock the completed workout before making changes.');return C.ensureLog(state,selectedDate)}
function progressModel(context){const model=P.buildProgress(state,C.CATALOG,progressFilters[context]);progressFilters[context]={...model.selection};return model}
function strengthPanel(context){return P.progressPanel(progressModel(context),context,progressSelected[context])}
function refreshProgress(context){const target=$(context+'StrengthPanel');if(target)target.innerHTML=strengthPanel(context)}
