function overview(log,done,total,meals){const target=N.targetsForDate(state,selectedDate);return `<div class="meneiOverview"><article class="card"><div class="eyebrow">Strength</div><h3>${h(log.title)}</h3><div class="metric">${done} <small>/ ${total} sets</small></div><div class="progressBar"><i style="width:${total?Math.min(100,done/total*100):0}%"></i></div><p class="sub">${log.exercises.length} exercises · ${h(gymFor(log)?.name)}</p><a class="btn small ghost" href="#todayWorkout">Your workout ↓</a></article><article class="card"><div class="eyebrow">Nutrition</div><h3>Fuel your progress.</h3><div class="metric">${Math.round(meals.protein)} <small>/ ${target.protein} g protein</small></div><div class="progressBar"><i style="width:${Math.min(100,meals.protein/(+target.protein||1)*100)}%"></i></div><p class="sub">${Math.round(meals.calories)} / ${target.calories} kcal eaten</p>${button('Your meal plan ↗','view','data-view="nutrition"','small ghost')}</article>${P.compactProgress(P.buildProgress(state,C.CATALOG))}</div>`}

let conflictReviewChangedValues=false;
function nutritionReviewSummary(value){return `Diet: ${h(value?.diet??'Any')} · Household cooking: ${h(value?.servings??1)}× · Meal repeat gap: ${h(value?.mealRepeatDays??2)} days`}
function savedConflictVersions(conflict){return `<div class="grid">${[['local','Saved version A'],['remote','Saved version B']].map(([key,label])=>`<section style="min-width:0"><h4>${label}</h4>${conflict.collection==='nutrition'?`<p class="sub">${nutritionReviewSummary(conflict[key])}</p>`:''}<pre style="font-size:10px;overflow:auto;max-height:200px;max-width:100%">${h(JSON.stringify(conflict[key],null,2))}</pre></section>`).join('')}</div>`}
function conflictsDialog(){
 const matching=state.conflicts.filter(C.conflictCopiesMatch),differing=state.conflicts.filter(conflict=>!C.conflictCopiesMatch(conflict)),reviewed=C.reviewedConflicts(state);
 const title=conflict=>conflict.collection==='nutrition'?'Nutrition settings':conflict.collection+' · '+conflict.key;
 const card=(conflict,isMatching)=>`<div class="card" style="margin:10px 0"><h3>${h(title(conflict))}</h3><p class="sub">${isMatching?'The two saved copies match in content. They may differ from your current settings.':h(conflict.reason)}</p><details><summary>Compare saved versions</summary><p class="sub">These copies were saved when the review was created. Neither label means your current settings.</p>${savedConflictVersions(conflict)}</details><div class="row wrap" style="margin-top:15px">${button(['profile','training','nutrition','reminders'].includes(conflict.collection)?'Keep current settings':'Keep current item','keep-current-conflict',`data-id="${h(conflict.id)}"`,'small primary')}${button('Use saved version A','resolve-conflict',`data-id="${h(conflict.id)}" data-choice="local"`,'small ghost')}${button('Use saved version B','resolve-conflict',`data-id="${h(conflict.id)}" data-choice="remote"`,'small ghost')}</div><p class="tiny">Keeping current leaves active values unchanged and saves both older copies for recovery.</p></div>`;
 const archive=reviewed.length?`<details class="collapsible"><summary>Reviewed copies · ${reviewed.length}</summary><p class="sub">Both saved versions and the value active at review remain in your backup. Restoring a reviewed copy changes the current value and saves it for recovery first.</p>${reviewed.map(entry=>{const conflict=entry.data?.conflict,current=entry.data?.current;return `<details class="card compact"><summary>${h(conflict?title(conflict):'Saved recovery copy')} · ${h(entry.reviewedAt||'')}</summary><p class="tiny">Review decision: ${h(entry.decision||'saved')}</p>${conflict?savedConflictVersions(conflict):''}<details><summary>Value active at review</summary><pre style="font-size:10px;overflow:auto;max-height:200px">${h(JSON.stringify(current,null,2))}</pre></details>${conflict?`<div class="row wrap">${button('Restore saved version A','restore-reviewed-conflict',`data-id="${h(entry.id)}" data-choice="local"`,'small ghost')}${button('Restore saved version B','restore-reviewed-conflict',`data-id="${h(entry.id)}" data-choice="remote"`,'small ghost')}${current?.exists===true?button('Restore value kept at review','restore-reviewed-conflict',`data-id="${h(entry.id)}" data-choice="current"`,'small ghost'):''}</div>`:''}</details>`}).join('')}</details>`:'';
 openModal(`<h2>Review saved versions</h2><p class="sub">Your current settings stay active until you choose an action. Reviewed copies remain available for recovery and in exported backups.</p><div class="callout"><b>Current nutrition settings</b><p>${nutritionReviewSummary(state.nutrition)}</p></div>${state.conflicts.length?`<p class="sub">${differing.length} differing ${differing.length===1?'item':'items'} · ${matching.length} matching ${matching.length===1?'item':'items'}. Differing saved copies appear first.</p>`:`<div class="empty">No pending reviews. ${conflictReviewChangedValues?'Your chosen values are active.':'Your current settings are unchanged.'} Close to sync.</div>`}${matching.length?`<div class="callout"><p>${matching.length} pairs contain matching saved content. Acknowledging them leaves all current settings unchanged and keeps both saved copies in Reviewed copies.</p>${button('Acknowledge '+matching.length+' matching copies','acknowledge-matching-conflicts','','small primary')}</div>`:''}${differing.map(conflict=>card(conflict,false)).join('')}${matching.length?`<details class="collapsible"><summary>Matching saved copies · ${matching.length}</summary>${matching.map(conflict=>card(conflict,true)).join('')}</details>`:''}${archive}`);
}
function applyConflictReview(change,{changesCurrent=false}={}){
 const before=C.clone(state);store.snapshot();
 try{change();save({sync:false});if(changesCurrent)conflictReviewChangedValues=true}catch(error){state=before;throw error}
 draw();conflictsDialog();
}
