$('avatarFile').addEventListener('change',async event=>{const context=workspaceContext(),file=event.target.files?.[0];if(!file)return;try{const photo=await preparePhoto(file);requireWorkspaceContext(context);const before=C.clone(state.profile);state.profile=C.touch({...state.profile,photo});try{save({render:true})}catch(e){state.profile=before;throw e}notify('Profile photo saved.')}catch(e){fail(e)}finally{event.target.value=''}});
$('backupFile').addEventListener('change',async event=>{const context=workspaceContext(),sequence=++backupReadSequence;pendingBackup=null;try{const file=event.target.files[0];if(!file)return;if(file.size>25*1024*1024)throw Error('Backup exceeds the 25 MB import limit.');const raw=JSON.parse(await file.text());requireWorkspaceContext(context);if(sequence!==backupReadSequence)return;const preview=C.previewSnapshot(state,raw),s=preview.summary;pendingBackup={preview,context};openModal(`<h2>Review backup import</h2><p class="sub">${h(file.name||'Selected backup')} · ${h(s.format)}</p><p>Your saved data has not changed. Merge adds records and keeps conflicting versions for review.</p><div class="card compact"><p>${s.workoutRecords} workout records · ${s.setRows} set rows</p><p>${s.mealItems} meal items · ${s.recipes} recipes · ${s.gyms} gyms</p><p>Backup units: ${h(s.sourceUnits)} · current units: ${h(s.currentUnits)}</p><p>${s.pendingReviews} pending reviews after merging</p></div><p class="sub">Counts include removed and preserved records. Your current account stays signed in. A recovery copy is saved before merging. Cancel leaves everything unchanged.</p><div class="modalButtons">${button('Cancel','close-modal','','small')}${button('Merge this backup','apply-backup','','primary')}</div>`)}catch(e){fail(e)}finally{event.target.value=''}});
function restOptions(){return restPreferences(localStorage,store.scope)}
function timerOptionsHtml(){const p=restOptions();return `<div class="row wrap restOptions">${button('Auto rest: '+(p.auto?'On':'Off'),'timer-auto',`aria-pressed="${p.auto}"`,'small')}${button('Sound: '+(p.sound?'On':'Off'),'timer-sound',`aria-pressed="${p.sound}"`,'small ghost')}</div>`}
function restoreRestTimer(){restTimer=new RestTimer({storage:sessionStorage,scope:store.scope,legacyCompatibility:true})}
function pauseRestTimer(){restAudio.silence();restTimer=null;if($('restDialog')?.open)$('restDialog').close();if($('restTray'))$('restTray').hidden=true;document.body?.classList.remove('hasRestTimer');restReturnFocus=null}
function startRestTimer(rest){if(!restTimer)restoreRestTimer();if(!restTimer.start({...rest,date:selectedDate}))return;if(restOptions().sound)void restAudio.arm();updateTimer()}
function stopRestTimer(){restTimer?.stop();restAudio.silence();if($('restDialog')?.open)$('restDialog').close();updateTimer();if(restReturnFocus){document.querySelector(restReturnFocus)?.focus();restReturnFocus=null}cloud?.schedule()}
function updateTimer(){
 const finished=restTimer?.tick();
 if(finished){notify(finished.kind==='pair'?'Pair rest complete. Stop timer to continue.':'Rest complete. Ready for your next set.');if(restOptions().sound)restAudio.cue();try{navigator.vibrate?.([150,50,150])}catch{}}
 const record=restTimer?.record,remaining=record?restTimer.remaining:120,display=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;
 for(const id of ['restTimer','restTrayTime','restDialogTime']){const target=$(id);if(target)target.textContent=display}
 if($('restTray'))$('restTray').hidden=!record||restTimer.blocking;
 document.body?.classList.toggle('hasRestTimer',!!record&&!restTimer.blocking);
 if(record){if($('restTrayLabel'))$('restTrayLabel').textContent=record.label;if($('restDialogLabel'))$('restDialogLabel').textContent=record.label;}
 if(restTimer?.blocking){
  if($('restDialogStatus'))$('restDialogStatus').textContent=remaining?'All working sets finished. Recover, breathe, and prepare for what is next.':'Rest complete. Stop timer to continue.';
  if($('restDialog')&&!$('restDialog').open){$('restDialog').showModal();$('restDialogStop')?.focus()}
 }else if($('restDialog')?.open)$('restDialog').close();
 for(const el of document.querySelectorAll('[data-action="timer-sound"]')){el.textContent='Sound: '+(restOptions().sound?'On':'Off');el.setAttribute('aria-pressed',String(restOptions().sound))}
}
$('restDialog')?.addEventListener('cancel',event=>{event.preventDefault();stopRestTimer()});
document.addEventListener('visibilitychange',updateTimer);
window.addEventListener('pageshow',updateTimer);
setInterval(updateTimer,500);
document.addEventListener('focusout',()=>cloud.schedule());
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event});
window.addEventListener('storage',event=>{if(!testCloudPreview||!invalidateChangedTabSession(cloud,event))return;Promise.resolve(cloud.onAccount?.(null)).then(()=>cloud.status('Cloud account changed in another tab. Sign in again in this tab; saved workspaces are preserved.')).catch(fail)});
// Register before CloudSync.start: its retained online listeners must observe
// a paused gate while this connection verifies auth and membership again.
window.addEventListener('offline',()=>{
 if(!needsBetaAdmission())return;
 ++betaConnectionSequence;++betaAdmissionSequence;betaNetworkAdmission=false;betaAdmissionContext=null;cloud.stop();cancelGymSearch();
 if(hasBetaWorkspace())cloud.status('Offline · Saved on this device. Cloud and AI resume after MENEI admission is verified.');
 else betaAccountChanged(cloud.session?.user).catch(error=>{if(!hasBetaWorkspace())showBetaEntry(error.message)});
});
window.addEventListener('online',async()=>{
 if(!needsBetaAdmission()||navigator.onLine===false)return;
 const connection=++betaConnectionSequence;++betaAdmissionSequence;
 pauseBetaWorkspace();showBetaEntry('Rechecking your MENEI account and beta place…');
 try{await loadRuntimeConfig();if(connection!==betaConnectionSequence||navigator.onLine===false)return;await restoreBetaSession()}
 catch(error){if(connection===betaConnectionSequence){pauseBetaWorkspace();showBetaEntry(error.message)}}
});
window.addEventListener('error',event=>{if(state)fail(Error('Something went wrong. Your saved data remains on this device. '+event.message))});
window.addEventListener('unhandledrejection',event=>fail(event.reason));
try{
 await loadRuntimeConfig();
 if(needsBetaAdmission()){
  cloud.stop();showBetaEntry('Sign in to open your MENEI workspace.');
  const callback=navigator.onLine===false?false:await cloud.acceptCallback();
  if(!callback)await restoreBetaSession();
  if(!hasBetaWorkspace())showBetaEntry(betaRecovery?'Enter a new password to recover your MENEI account.':betaEntryMessage);
  if('serviceWorker' in navigator)registerOffline().catch(e=>setCloudStatus('Offline installation unavailable: '+e.message));
 }else{
state=store.load(cloud.session?.user?.id||'guest');const upgrade=U.commitDeviceUpgrade(store,localStorage);state=upgrade.state;state.leftovers??=[];state.routines??=[];state.resolvedConflicts??=[];seedRecipes();restoreRestTimer();const response=await fetch('./media-manifest.json');if(response.ok)media=await response.json();save({sync:false});view='today';if(location.hash==='#recipes'){view='nutrition';nutritionTab='recipes'}if(location.hash==='#program')view='program';if(location.hash==='#library')view='library';draw();if(localPreview||testCloudPreview)setCloudStatus(cloud.lastStatus);if('serviceWorker' in navigator)registerOffline().catch(e=>setCloudStatus('Offline installation unavailable: '+e.message));const callback=await cloud.acceptCallback();if(!callback)await cloud.restoreSession();cloud.start();
 }
}catch(e){
 if(needsBetaAdmission()){pauseBetaWorkspace();showBetaEntry(e.message)}
 else $('app').innerHTML=`<div class="card"><h1>The app could not open.</h1><p class="error">${h(e.message)}</p><p class="sub">Existing stored data was not cleared. Keep your original app and JSON backup.</p>${e instanceof BetaBrowserContextError?'<a class="btn primary" href="/beta">Open beta admission</a>':U.originalDeviceBackup(localStorage)?button('Export original backup','export-original','','primary'):''}</div>`;
}
